const payload = $('ISC Webhook — schedule.monthly_scorecard').first().json.body;
const suppliers = $input.first().json.suppliers ?? [];
const month = new Date().toLocaleString('en-GB', { month: 'long', year: 'numeric' });
const recipientEmail = payload.recipientEmail ?? payload.email ?? 'REPLACE_WITH_RECIPIENT@example.com';
const userName = payload.userName ?? payload.name ?? 'Client';

const getColor = (score) => {
  if (!score && score !== 0) return '#94a3b8';
  if (score >= 80) return '#16a34a';
  if (score >= 60) return '#d97706';
  return '#dc2626';
};

const rows = suppliers.map((s, i) => `
  <tr style="background:${i % 2 === 0 ? '#f8fafc' : 'white'}">
    <td style="padding:10px 14px;border-bottom:1px solid #e2e8f0">${s.name ?? '—'}</td>
    <td style="padding:10px 14px;border-bottom:1px solid #e2e8f0;color:#64748b">${s.category ?? '—'}</td>
    <td style="padding:10px 14px;border-bottom:1px solid #e2e8f0;font-weight:bold;color:${getColor(s.overallScore)}">${s.overallScore ?? '—'}</td>
    <td style="padding:10px 14px;border-bottom:1px solid #e2e8f0;color:#64748b">${s.qualityScore ?? '—'}</td>
    <td style="padding:10px 14px;border-bottom:1px solid #e2e8f0;color:#64748b">${s.deliveryScore ?? '—'}</td>
    <td style="padding:10px 14px;border-bottom:1px solid #e2e8f0;color:#64748b">${s.costScore ?? '—'}</td>
  </tr>`).join('');

const html = `<!DOCTYPE html>
<html>
<body style="font-family:Arial,sans-serif;max-width:750px;margin:0 auto;padding:20px;color:#1e293b">
  <div style="background:linear-gradient(135deg,#1e3a5f,#0ea5e9);padding:24px;border-radius:12px 12px 0 0;color:white">
    <h1 style="margin:0;font-size:22px">📦 Monthly Supplier Scorecard</h1>
    <p style="margin:8px 0 0;opacity:0.85">${month}</p>
  </div>
  <div style="border:1px solid #e2e8f0;border-top:none;padding:24px;border-radius:0 0 12px 12px">
    <p>Dear ${userName},</p>
    <p>Here is your supplier performance scorecard for <strong>${month}</strong>:</p>
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead>
        <tr style="background:#1e3a5f;color:white">
          <th style="padding:10px 14px;text-align:left">Supplier</th>
          <th style="padding:10px 14px;text-align:left">Category</th>
          <th style="padding:10px 14px;text-align:left">Overall</th>
          <th style="padding:10px 14px;text-align:left">Quality</th>
          <th style="padding:10px 14px;text-align:left">Delivery</th>
          <th style="padding:10px 14px;text-align:left">Cost</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>
    <div style="margin-top:24px;text-align:center">
      <a href="https://YOUR_ISC_DOMAIN/scorecard" style="background:#0ea5e9;color:white;padding:12px 24px;border-radius:8px;text-decoration:none;font-weight:bold">View Full Scorecard →</a>
    </div>
  </div>
</body>
</html>`;

return [{ json: { html, recipientEmail, month } }];
